/* eslint-disable space-in-parens */

import Complex64Array = require( '@stdlib/array/complex64' );
import clastIndexOfFalsy = require( './index' );


// TESTS //

// The function returns a number...
{
	var x = new Complex64Array( [ 1.0, 2.0, 3.0, 4.0, 0.0, 0.0 ] );

	clastIndexOfFalsy( x.length, x, 1 ); // $ExpectType number
}

// The compiler throws an error if the function is provided a first argument which is not a number...
{
	var x = new Complex64Array( [ 1.0, 2.0, 3.0, 4.0, 0.0, 0.0 ] );

	clastIndexOfFalsy( '1', x, 1 ); // $ExpectError
	clastIndexOfFalsy( true, x, 1 ); // $ExpectError
	clastIndexOfFalsy( false, x, 1 ); // $ExpectError
	clastIndexOfFalsy( null, x, 1 ); // $ExpectError
	clastIndexOfFalsy( {}, x, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a Complex64Array...
{
	clastIndexOfFalsy( 3, '1', 1 ); // $ExpectError
	clastIndexOfFalsy( 3, true, 1 ); // $ExpectError
	clastIndexOfFalsy( 3, false, 1 ); // $ExpectError
	clastIndexOfFalsy( 3, null, 1 ); // $ExpectError
	clastIndexOfFalsy( 3, {}, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a third argument which is not a number...
{
	var x = new Complex64Array( [ 1.0, 2.0, 3.0, 4.0, 0.0, 0.0 ] );

	clastIndexOfFalsy( x.length, x, '1' ); // $ExpectError
	clastIndexOfFalsy( x.length, x, true ); // $ExpectError
	clastIndexOfFalsy( x.length, x, false ); // $ExpectError
	clastIndexOfFalsy( x.length, x, null ); // $ExpectError
	clastIndexOfFalsy( x.length, x, {} ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	clastIndexOfFalsy(); // $ExpectError
	clastIndexOfFalsy( 3 ); // $ExpectError
	clastIndexOfFalsy( 3, new Complex64Array( [ 1.0, 2.0, 3.0, 4.0, 0.0, 0.0 ] ) ); // $ExpectError
	clastIndexOfFalsy( 3, new Complex64Array( [ 1.0, 2.0, 3.0, 4.0, 0.0, 0.0 ] ), 1, {} ); // $ExpectError
}

// Attached to main export is an `ndarray` method which returns a number...
{
	var x = new Complex64Array( [ 1.0, 2.0, 3.0, 4.0, 0.0, 0.0 ] );

	clastIndexOfFalsy.ndarray( x.length, x, 1, 0 ); // $ExpectType number
}

// The compiler throws an error if the `ndarray` method is provided a first argument which is not a number...
{
	var x = new Complex64Array( [ 1.0, 2.0, 3.0, 4.0, 0.0, 0.0 ] );

	clastIndexOfFalsy.ndarray( '1', x, 1, 1 ); // $ExpectError
	clastIndexOfFalsy.ndarray( true, x, 1, 1 ); // $ExpectError
	clastIndexOfFalsy.ndarray( false, x, 1, 1 ); // $ExpectError
	clastIndexOfFalsy.ndarray( null, x, 1, 1 ); // $ExpectError
	clastIndexOfFalsy.ndarray( {}, x, 1, 1 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a second argument which is not a Complex64Array...
{
	clastIndexOfFalsy.ndarray( 3, '1', 1, 1 ); // $ExpectError
	clastIndexOfFalsy.ndarray( 3, true, 1, 1 ); // $ExpectError
	clastIndexOfFalsy.ndarray( 3, false, 1, 1 ); // $ExpectError
	clastIndexOfFalsy.ndarray( 3, null, 1, 1 ); // $ExpectError
	clastIndexOfFalsy.ndarray( 3, {}, 1, 1 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a third argument which is not a number...
{
	var x = new Complex64Array( [ 1.0, 2.0, 3.0, 4.0, 0.0, 0.0 ] );

	clastIndexOfFalsy.ndarray( x.length, x, '1', 1 ); // $ExpectError
	clastIndexOfFalsy.ndarray( x.length, x, true, 1 ); // $ExpectError
	clastIndexOfFalsy.ndarray( x.length, x, false, 1 ); // $ExpectError
	clastIndexOfFalsy.ndarray( x.length, x, null, 1 ); // $ExpectError
	clastIndexOfFalsy.ndarray( x.length, x, {}, 1 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a fourth argument which is not a number...
{
	var x = new Complex64Array( [ 1.0, 2.0, 3.0, 4.0, 0.0, 0.0 ] );

	clastIndexOfFalsy.ndarray( x.length, x, 1, '1' ); // $ExpectError
	clastIndexOfFalsy.ndarray( x.length, x, 1, true ); // $ExpectError
	clastIndexOfFalsy.ndarray( x.length, x, 1, false ); // $ExpectError
	clastIndexOfFalsy.ndarray( x.length, x, 1, null ); // $ExpectError
	clastIndexOfFalsy.ndarray( x.length, x, 1, {} ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided an unsupported number of arguments...
{
	clastIndexOfFalsy.ndarray(); // $ExpectError
	clastIndexOfFalsy.ndarray( 3 ); // $ExpectError
	clastIndexOfFalsy.ndarray( 3, new Complex64Array( [ 1.0, 2.0, 3.0, 4.0, 0.0, 0.0 ] ) ); // $ExpectError
	clastIndexOfFalsy.ndarray( 3, new Complex64Array( [ 1.0, 2.0, 3.0, 4.0, 0.0, 0.0 ] ), 1 ); // $ExpectError
	clastIndexOfFalsy.ndarray( 3, new Complex64Array( [ 1.0, 2.0, 3.0, 4.0, 0.0, 0.0 ] ), 1, 0, {} ); // $ExpectError
}
